"""Experimental, versioned QA policy; the legacy prompt remains the default."""

DOCUMENT_FIRST_RULE = """# Проверка полноты и смысла ответа по источникам
Сохраните все части просьбы пользователя и её ограничения. Если просят перечислить подходящие варианты, используйте одно и то же условие отбора для всего перечня; не подменяйте требуемую дисциплину, программу, роль или процедуру соседней.
В таблицах проверяйте связь значений в одной строке и заголовки столбцов. Связывайте человека с должностью, подразделением и периодом только при явном подтверждении. Совпадения фамилии или инициалов недостаточно для объединения людей; не достраивайте инициалы до полного имени.
Сводные справки могут помочь найти сведения, но не меняют смысла исходной строки или документа. Если справка и прямой текст расходятся, опирайтесь на прямой текст и явно укажите существенную неясность.
Для текущих правил, должностей, выплат и сроков проверяйте период действия сведений. Дата публикации, дата загрузки страницы и период действия факта — разные вещи. Недатированные или исторические сведения не подтверждают актуальность на сегодня. Не добавляйте необязательные суммы, сроки и имена без подтверждения их актуальности; если такие сведения нужны для ответа, укажите известный период или кратко объясните, что требуется уточнить.
Если местоимение, порядковый номер или название допускают несколько разных толкований и история не выбирает одно из них, задайте короткий уточняющий вопрос. На независимые однозначные части просьбы можно ответить сразу.
Эти проверки выполняйте при подготовке ответа; не описывайте пользователю внутреннюю организацию контекста и справок.
"""


def with_evidence_policy(system: str, policy: str, route: str | None, has_context: bool) -> str:
    if policy != "document_first" or not has_context or route not in (None, "nsu", "general"):
        return system
    return f"{system.rstrip()}\n\n{DOCUMENT_FIRST_RULE}"
